select json_build_object('columns',(select json_agg(x) from (select c.relname as table_name,a.attname as column_name,format_type(a.atttypid,a.atttypmod) as type,a.attnotnull as not_null,pg_get_expr(d.adbin,d.adrelid) as default_value,a.attidentity as identity,a.attgenerated as generated from pg_class c join pg_namespace n on n.oid=c.relnamespace join pg_attribute a on a.attrelid=c.oid and a.attnum>0 and not a.attisdropped left join pg_attrdef d on d.adrelid=c.oid and d.adnum=a.attnum where n.nspname='public' and c.relkind in ('r','p') order by c.relname,a.attnum)x),'enums',(select json_agg(x) from (select t.typname,array_agg(e.enumlabel order by e.enumsortorder) as labels from pg_type t join pg_namespace n on n.oid=t.typnamespace join pg_enum e on e.enumtypid=t.oid where n.nspname='public' group by t.typname)x),'acls',(select json_agg(json_build_object('name',c.relname,'kind',c.relkind,'acl',c.relacl::text,'options',c.reloptions)) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind in ('r','p','v','S')),'schema_acl',(select nspacl::text from pg_namespace where nspname='public')) as schema_metadata;
